#include <iostream>
#include <cstring>
#include <queue>
#include <algorithm>
#include <utility>
using namespace std;

typedef pair<int, int> pii;
#define mp make_pair
#define F first
#define S second
const int oo = 10000000;
const int N = 300;
const int M = 900000;

int level[N], adj[N], copy_adj[N], fila[N];
int to[M], ant[M], cap[M], pa;
int n, t;
int dx[] = {-1, 0, 1, 0};
int dy[] = {0, 1, 0, -1};
pii q[N];
int inds[21][21], inds2[21][21], mk[21][21], c[21][21];
char gr[21][21], gr2[21][21];
int rp, cp, S, T;

void add(int f, int t, int c_val) {
    to[pa] = t, cap[pa] = c_val, ant[pa] = adj[f]; adj[f] = pa; pa++;
    swap(f, t);
    c_val = 0;
    to[pa] = t, cap[pa] = c_val, ant[pa] = adj[f]; adj[f] = pa; pa++;
}

int bfs(int source, int sink) {
    memset(level, -1, sizeof level);
    level[source] = 0;
    int pos = 0, tam = 0;
    fila[tam++] = source;
    while (pos < tam) {
        int now = fila[pos++];
        for (int i = adj[now]; i >= 0; i = ant[i]) {
            if (cap[i] && level[to[i]] == -1) {
                level[to[i]] = level[now] + 1;
                fila[tam++] = to[i];
            }
        }
    }
    return level[sink] != -1;
}

int dfs(int no, int sink, int flow) {
    if (no == sink) return flow;
    for (int &i = copy_adj[no]; i >= 0; i = ant[i]) {
        if (cap[i] && level[no] + 1 == level[to[i]]) {
            int nflow = dfs(to[i], sink, min(flow, cap[i]));
            if (nflow) {
                cap[i] -= nflow; cap[i^1] += nflow;
                return nflow;
            }
        }
    }
    return 0;
}

int maxflow(int source, int sink) {
    int mf = 0;
    while (true) {
        if (bfs(source, sink)) {
            memcpy(copy_adj, adj, sizeof adj);
            while (true) {
                int add_val = dfs(source, sink, 1<<30);
                if (add_val) mf += add_val;
                else break;
            }
        } else break;
    }
    return mf;
}

bool valid(int a, int b) {
    return a >= 0 && a < n && b >= 0 && b < n;
}

void busc(int a, int b) {
    int ini = 0, fim = 0;
    memset(mk, 0, sizeof mk);
    memset(c, -1, sizeof c);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (gr[i][j] == 'Y') mk[i][j] = 1;
        }
    }
    q[fim++] = mp(rp, cp);
    q[fim++] = mp(a, b);
    c[a][b] = c[rp][cp] = 0;
    mk[a][b] = 1;
    mk[rp][cp] = 2;
    while (ini < fim) {
        pii now = q[ini++];
        if (mk[now.F][now.S] == 1 && gr2[now.F][now.S] > '0' && gr2[now.F][now.S] <= '9') {
            add(inds[a][b], inds2[now.F][now.S], 9);
        }
        if (mk[now.F][now.S] == 1 && c[now.F][now.S] == t) {
            continue;
        }
        for (int i = 0; i < 4; i++) {
            int nx = now.F + dx[i], ny = now.S + dy[i];
            if (valid(nx, ny) && mk[nx][ny] == 0) {
                mk[nx][ny] = mk[now.F][now.S];
                c[nx][ny] = c[now.F][now.S] + 1;
                q[fim++] = mp(nx, ny);
            } else if (mk[now.F][now.S] == 1 && valid(nx, ny) && mk[nx][ny] == 2 && c[nx][ny] == c[now.F][now.S] + 1 && gr2[nx][ny] > '0' && gr2[nx][ny] <= '9') {
                add(inds[a][b], inds2[nx][ny], 9);
            }
        }
    }
}

int main() {
    cin >> n >> t;
    S = 202, T = 203;
    memset(adj, -1, sizeof adj);
    pa = 0;
    memset(inds, -1, sizeof inds);
    memset(inds2, -1, sizeof inds2);
    for (int i = 0; i < n; i++) {
        cin >> gr[i];
        for (int j = 0; j < n; j++) {
            if (gr[i][j] > '0' && gr[i][j] <= '9') {
                add(S, i * n + j, gr[i][j] - '0');
                inds[i][j] = i * n + j;
            }
            if (gr[i][j] == 'Z') rp = i, cp = j;
        }
    }
    for (int i = 0; i < n; i++) {
        cin >> gr2[i];
        for (int j = 0; j < n; j++) {
            if (gr2[i][j] > '0' && gr2[i][j] <= '9') {
                add(i * n + j, T, gr2[i][j] - '0');
                inds2[i][j] = i * n + j;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (gr[i][j] > '0' && gr[i][j] <= '9' && gr2[i][j] > '0' && gr2[i][j] <= '9') {
                add(inds[i][j], inds2[i][j], 9);
            }
            if (gr[i][j] > '0' && gr[i][j] <= '9') {
                busc(i, j);
            }
        }
    }
    cout << maxflow(S, T) << endl;
    return 0;
}
